+package com.example.customers;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.customers.domain.QueryLog;
+
+import com.microsoft.playwright.Locator;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+
+/**
+ * Drives the running application in a real browser: checks what the address bar
+ * says and what typing costs the backend. Run with {@code mvn -o test -Dtest=CustomerListBrowserTest}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserTest extends AbstractBasePlaywrightIT {
+
+    static {
+        // Chromium runs without a window; the base class reads this property.
+        System.setProperty("headless", "true");
+    }
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Test
+    void typingNarrowsTheListAndWritesTheAddressWithoutAddingHistory() {
+        int historyBefore = historyLength();
+
+        nameFilter().pressSequentially("vir", new Locator.PressSequentiallyOptions().setDelay(50));
+
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+        assertEquals(15, GridElement.get(page).getTotalRowCount());
+        assertThat(page).hasURL(getUrl() + "?name=vir");
+        assertEquals(historyBefore, historyLength(), "Typing must not add history entries");
+    }
+
+    @Test
+    void openingAnAddressRestoresTheFilter() {
+        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        assertThat(nameFilter()).hasValue("vir");
+        MultiSelectComboBoxElement.getByLabel(page, "Status").assertSelectedItems("ACTIVE", "CLOSED");
+        assertThat(page.getByText("Showing 10 of 500")).isVisible();
+    }
+
+    @Test
+    void openingAnAddressWithAnEncodedSpaceFindsBothWords() {
+        page.navigate(getUrl() + "?name=ada+aal");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        assertThat(nameFilter()).hasValue("ada aal");
+        assertThat(page.getByText("Showing 2 of 500")).isVisible();
+    }
+
+    @Test
+    void clearingTheFilterLeavesNoParametersBehind() {
+        page.navigate(getUrl() + "?name=vir&status=CLOSED");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        nameFilter().fill("");
+        MultiSelectComboBoxElement.getByLabel(page, "Status").deselectItem("CLOSED");
+
+        assertThat(page.getByText("Showing 500 of 500")).isVisible();
+        assertThat(page).hasURL(getUrl());
+    }
+
+    @Test
+    void statusesAreWrittenInDeclarationOrder() {
+        MultiSelectComboBoxElement status = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        status.selectItem("CLOSED");
+        status.selectItem("ACTIVE");
+
+        assertThat(page.getByText("Showing 333 of 500")).isVisible();
+        assertThat(page).hasURL(getUrl() + "?status=ACTIVE,CLOSED");
+    }
+
+    /** Typing a nine-letter name, one key every 100 ms, must not query the backend once per key. */
+    @Test
+    void aNineLetterNameCostsOneBurstOfQueries() {
+        queryLog.clear();
+
+        nameFilter().pressSequentially("bergström", new Locator.PressSequentiallyOptions().setDelay(100));
+
+        assertThat(page.getByText("Showing 14 of 500")).isVisible();
+        assertThat(page).hasURL(getUrl() + "?name=bergstr%C3%B6m");
+        int queries = queryLog.pageQueries().size() + queryLog.countQueries().size();
+        assertTrue(queries <= 2, "Typing one name cost " + queries + " queries: pages="
+                + queryLog.pageQueries() + " counts=" + queryLog.countQueries());
+    }
+
+    @Test
+    void aSpaceInTheNameIsWrittenAsPercent20() {
+        nameFilter().pressSequentially("ada aal", new Locator.PressSequentiallyOptions().setDelay(50));
+
+        assertThat(page.getByText("Showing 2 of 500")).isVisible();
+        assertThat(page).hasURL(getUrl() + "?name=ada%20aal");
+    }
+
+    @Test
+    void reloadingTheAddressKeepsTheFilter() {
+        nameFilter().pressSequentially("vir", new Locator.PressSequentiallyOptions().setDelay(50));
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+
+        page.reload();
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        assertThat(nameFilter()).hasValue("vir");
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+    }
+
+    private Locator nameFilter() {
+        // The placeholder is on both the vaadin-text-field and its inner input; the input is the one to type into.
+        return page.locator("input[placeholder='Filter by name']");
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("history.length")).intValue();
+    }
+}
